const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Obolon, Ukraine (Kyiv district)
  const obolon = ee.Geometry.Point([30.50, 50.51]).buffer(3000); // 3km radius

  // 2. Load VIIRS Nighttime Lights monthly composites
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .select('avg_rad');

  // 3. Get March 2022 data
  const march2022 = viirs
    .filterDate('2022-03-01', '2022-03-31')
    .filterBounds(obolon);

  const marchSize = march2022.size().getInfo();
  console.log('March 2022 images:', marchSize);

  if (marchSize === 0) {
    console.log('No data for March 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get May 2022 data
  const may2022 = viirs
    .filterDate('2022-05-01', '2022-05-31')
    .filterBounds(obolon);

  const maySize = may2022.size().getInfo();
  console.log('May 2022 images:', maySize);

  if (maySize === 0) {
    console.log('No data for May 2022.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate mean nighttime lights for both periods
  const marchImg = march2022.mean();
  const mayImg = may2022.mean();

  // 6. Check pixel counts
  const marchCount = marchImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log('March valid pixels:', marchCount);

  if (marchCount === 0) {
    console.log('No valid pixels in March 2022.');
    console.log('<answer>C2</answer>');
    return;
  }

  const mayCount = mayImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log('May valid pixels:', mayCount);

  if (mayCount === 0) {
    console.log('No valid pixels in May 2022.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Calculate mean radiance values
  const marchRadiance = marchImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const mayRadiance = mayImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: obolon,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log('March 2022 mean radiance:', marchRadiance);
  console.log('May 2022 mean radiance:', mayRadiance);

  // 8. Validation and final answer
  if (marchRadiance === null || mayRadiance === null || 
      isNaN(marchRadiance) || isNaN(mayRadiance) ||
      marchRadiance < 0 || mayRadiance < 0) {
    console.log('Invalid radiance values calculated.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log('Change:', ((mayRadiance - marchRadiance) / marchRadiance * 100).toFixed(2) + '%');

  if (mayRadiance < marchRadiance) {
    console.log('Nighttime lights decreased from March to May 2022.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Nighttime lights did not decrease from March to May 2022.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
